All confirmed: `Client(transport)` accepts a `FastMCP` instance directly (uses in-memory `FastMCPTransport`), and `read_resource(uri)` is async, returning a list of `TextResourceContents`/`BlobResourceContents`.

```python
import asyncio

from fastmcp import FastMCP
from fastmcp.client import Client


mcp = FastMCP("ConfigServer")


@mcp.resource("data://config")
def get_config() -> dict:
    return {"debug": True, "version": "1.0.0"}


async def main() -> None:
    client = Client(mcp)

    async with client:
        contents = await client.read_resource("data://config")
        for item in contents:
            if hasattr(item, "text"):
                print(item.text)
            else:
                print(item.blob)


if __name__ == "__main__":
    asyncio.run(main())
